import "fmt"

type Command interface {
	Execute()
	Undo()
}

type Document struct{ Content string }

type AppendTextCommand struct {
	doc  *Document
	text string
}

func (c *AppendTextCommand) Execute() { c.doc.Content += c.text }
func (c *AppendTextCommand) Undo()    { c.doc.Content = c.doc.Content[:len(c.doc.Content)-len(c.text)] }

func main() {
	doc := &Document{}
	cmd := &AppendTextCommand{doc: doc, text: "Привет, Мир!"}

	cmd.Execute()
	fmt.Println("После Execute:", doc.Content)

	cmd.Undo()
	fmt.Println("После Undo:   ", doc.Content)
}

package main

import (
	"context"
	"fmt"
	"time"
)

type DataFetcher struct{}

func (df DataFetcher) Fetch(ctx context.Context, query string) (string, error) {
	select {
	case <-time.After(100 * time.Millisecond):
		return "Данные по запросу: " + query, nil
	case <-ctx.Done():
		return "", ctx.Err()
	}
}

func main() {
	df := DataFetcher{}

	// Таймаут 50мс (операция требует 100мс):
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	_, err := df.Fetch(ctx, "analytics")
	if err != nil {
		fmt.Println("❌ Запрос отменен по таймауту:", err)
	}
}
